#!/usr/bin/env python3
from __future__ import annotations

import json
import os
from typing import Any

import anthropic


def cases(mode: str) -> dict[str, dict[str, Any]]:
    if mode == "permissive":
        return {
            "inline_position_preserved": {
                "messages": [
                    {"role": "user", "content": "PERMISSIVE_USER_1"},
                    {"role": "assistant", "content": "PERMISSIVE_ASSISTANT"},
                    {"role": "system", "content": "PERMISSIVE_INLINE_SENTINEL"},
                    {"role": "user", "content": "PERMISSIVE_USER_2"},
                ],
                "stream": True,
            }
        }
    if mode == "restrictive_sentinel":
        return {
            "all_system_content_preserved": {
                "messages": [
                    {"role": "system", "content": "LEAD_SENTINEL"},
                    {"role": "user", "content": "diagnostic user turn"},
                    {"role": "assistant", "content": "diagnostic assistant turn"},
                    {"role": "system", "content": "INLINE_SENTINEL"},
                    {"role": "user", "content": "continue"},
                ],
                "stream": True,
            }
        }
    return {
        "production_issue_shape": {
            "messages": [
                {"role": "system", "content": "You are a helpful assistant."},
                {"role": "user", "content": "Check the GPU status for vLLM."},
                {"role": "assistant", "content": "I will check it."},
                {"role": "user", "content": "Show the nvidia-smi output."},
                {"role": "assistant", "content": "Utilization is around 15%."},
                {"role": "user", "content": "Write a report."},
                {"role": "system", "content": "Summarize the conversation as a GPU report."},
                {"role": "user", "content": "Please summarize it."},
            ],
            "stream": True,
        },
        "inline_after_user_without_leading_system": {
            "messages": [
                {"role": "user", "content": "Earlier context"},
                {"role": "assistant", "content": "Earlier response"},
                {"role": "system", "content": "Apply the hidden task instruction."},
                {"role": "user", "content": "Continue."},
            ]
        },
        "multiple_inline_system_messages": {
            "messages": [
                {"role": "system", "content": "Global instruction."},
                {"role": "user", "content": "First question"},
                {"role": "system", "content": "First auxiliary instruction."},
                {"role": "assistant", "content": "Intermediate answer"},
                {"role": "system", "content": "Second auxiliary instruction."},
                {"role": "user", "content": "Final question"},
            ],
            "stream": True,
        },
        "top_level_and_inline_system": {
            "system": "TOP_LEVEL_SYSTEM_SENTINEL",
            "messages": [
                {"role": "user", "content": "User context"},
                {"role": "system", "content": "INLINE_SYSTEM_SENTINEL"},
                {"role": "user", "content": "Final request"},
            ]
        },
        "system_text_blocks": {
            "messages": [
                {"role": "system", "content": [{"type": "text", "text": "Leading block."}]},
                {"role": "user", "content": "Context"},
                {"role": "system", "content": [
                    {"type": "text", "text": "Inline block one."},
                    {"type": "text", "text": "Inline block two."},
                ]},
                {"role": "user", "content": "Continue"},
            ]
        },
        "empty_inline_system": {
            "messages": [
                {"role": "system", "content": "Leading instruction."},
                {"role": "user", "content": "Context"},
                {"role": "system", "content": ""},
                {"role": "user", "content": "Continue"},
            ]
        },
        "long_context_inline_system": {
            "messages": [
                {"role": "system", "content": "Global policy."},
                *[
                    {"role": "user" if index % 2 == 0 else "assistant",
                     "content": f"Historical turn {index}: " + "context " * 20}
                    for index in range(12)
                ],
                {"role": "system", "content": "Compress the history before answering."},
                {"role": "user", "content": "Give the final answer."},
            ]
        },
    }


def error(exc: Exception) -> dict[str, Any]:
    if isinstance(exc, anthropic.APIStatusError):
        return {"ok": False, "status": exc.status_code, "body": exc.response.text}
    return {"ok": False, "exception": type(exc).__name__, "message": str(exc)}


def count_tokens(client, model, case):
    try:
        kwargs = {"model": model, "messages": case["messages"]}
        if "system" in case:
            kwargs["system"] = case["system"]
        response = client.messages.count_tokens(**kwargs)
        assert response.input_tokens > 0
        return {"ok": True, "status": 200, "input_tokens": response.input_tokens}
    except Exception as exc:
        return error(exc)


def create_message(client, model, case):
    try:
        kwargs = {"model": model, "max_tokens": 1, "messages": case["messages"]}
        if "system" in case:
            kwargs["system"] = case["system"]
        response = client.messages.create(**kwargs)
        assert response.role == "assistant"
        return {"ok": True, "status": 200, "role": response.role,
                "stop_reason": response.stop_reason}
    except Exception as exc:
        return error(exc)


def stream_message(client, model, case):
    try:
        kwargs = {"model": model, "max_tokens": 1, "messages": case["messages"]}
        if "system" in case:
            kwargs["system"] = case["system"]
        event_count = 0
        with client.messages.stream(**kwargs) as stream:
            for _ in stream:
                event_count += 1
            final = stream.get_final_message()
        assert final.role == "assistant"
        assert event_count > 0
        return {"ok": True, "status": 200, "events": event_count,
                "role": final.role}
    except Exception as exc:
        return error(exc)


def main() -> int:
    mode = os.environ["PROBE_MODE"]
    model = os.environ["SERVED_MODEL"]
    client = anthropic.Anthropic(api_key="test", base_url=os.environ["ANTHROPIC_BASE_URL"],
                                 timeout=60, max_retries=0)
    results = {}
    for name, case in cases(mode).items():
        result = {
            "count_tokens": count_tokens(client, model, case),
            "messages": create_message(client, model, case),
        }
        if case.get("stream"):
            result["stream"] = stream_message(client, model, case)
        results[name] = result
    payload = {"mode": mode, "model": model, "cases": results}
    print(json.dumps(payload, ensure_ascii=False, sort_keys=True), flush=True)
    return 0 if all(
        operation["ok"]
        for case in results.values()
        for operation in case.values()
    ) else 1


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
import json
import sys

EXPECTED = {
    "official_qwen": {
        "production_issue_shape", "inline_after_user_without_leading_system",
        "multiple_inline_system_messages", "top_level_and_inline_system",
        "system_text_blocks", "empty_inline_system", "long_context_inline_system",
    },
    "restrictive_sentinel": {"all_system_content_preserved"},
    "permissive": {"inline_position_preserved"},
}
STREAM_CASES = {
    "official_qwen": {"production_issue_shape", "multiple_inline_system_messages"},
    "restrictive_sentinel": {"all_system_content_preserved"},
    "permissive": {"inline_position_preserved"},
}

def main() -> int:
    valid = True
    summaries = {}
    for path in sys.argv[1:]:
        payload = json.load(open(path))
        mode = payload["mode"]
        cases = payload["cases"]
        valid &= set(cases) == EXPECTED[mode]
        for name, result in cases.items():
            valid &= result["count_tokens"]["ok"] is True
            valid &= result["count_tokens"]["input_tokens"] > 0
            valid &= result["messages"]["ok"] is True
            valid &= result["messages"]["role"] == "assistant"
            if name in STREAM_CASES[mode]:
                valid &= result["stream"]["ok"] is True
                valid &= result["stream"]["events"] > 0
        summaries[mode] = {"cases": len(cases), "all_ok": valid}
    print(summaries)
    return 0 if valid and set(summaries) == set(EXPECTED) else 1

if __name__ == "__main__":
    raise SystemExit(main())

"""Verifier-owned fixtures that exercise the public KV connector contract."""

from __future__ import annotations

import hashlib
import json
import threading
import time
from dataclasses import dataclass, field
from pathlib import Path

import torch

from vllm import SamplingParams
from vllm.config import (
    CacheConfig,
    DeviceConfig,
    KVTransferConfig,
    ModelConfig,
    SchedulerConfig,
    VllmConfig,
)
from vllm.distributed.kv_transfer.kv_connector.factory import KVConnectorFactory
from vllm.distributed.kv_transfer.kv_connector.v1.base import (
    KVConnectorBase_V1,
    KVConnectorMetadata,
    KVConnectorRole,
)
from vllm.utils.hashing import sha256
from vllm.v1.core.kv_cache_utils import get_request_block_hasher, init_none_hash
from vllm.v1.core.sched.scheduler import Scheduler
from vllm.v1.kv_cache_interface import (
    FullAttentionSpec,
    KVCacheConfig,
    KVCacheGroupSpec,
)
from vllm.v1.outputs import KVConnectorOutput, ModelRunnerOutput
from vllm.v1.request import Request
from vllm.v1.structured_output import StructuredOutputManager


@dataclass(frozen=True)
class TransferRecord:
    request_id: str
    matched_tokens: int
    block_ids: tuple[int, ...]


@dataclass
class AsyncTransferMetadata(KVConnectorMetadata):
    transfers: list[TransferRecord] = field(default_factory=list)


class AsyncMemoryConnector(KVConnectorBase_V1):
    """Hidden connector that performs an actual asynchronous memory copy."""

    def __init__(self, vllm_config, role, kv_cache_config=None):
        super().__init__(vllm_config, role, kv_cache_config)
        extra = vllm_config.kv_transfer_config.kv_connector_extra_config
        self._matches = {str(k): int(v) for k, v in extra.get("matches", {}).items()}
        self._sync_ids = set(extra.get("sync_request_ids", ()))
        self._delays = {
            str(k): float(v) / 1000 for k, v in extra.get("delays_ms", {}).items()
        }
        self._failures = {
            str(k): int(v) for k, v in extra.get("failure_block_index", {}).items()
        }
        self._pending: list[TransferRecord] = []
        self._request_blocks: dict[str, set[int]] = {}
        self._completed: set[str] = set()
        self._invalid_blocks: set[int] = set()
        self._checksums: dict[str, str] = {}
        self._threads: list[threading.Thread] = []
        self._lock = threading.Lock()

    def get_num_new_matched_tokens(self, request, num_computed_tokens):
        matched = self._matches.get(request.request_id, 0)
        return matched, matched > 0 and request.request_id not in self._sync_ids

    def update_state_after_alloc(self, request, blocks, num_external_tokens):
        if num_external_tokens <= 0 or request.request_id in self._sync_ids:
            return
        groups = blocks.get_block_ids()
        block_ids = tuple(groups[0]) if groups else ()
        self._request_blocks[request.request_id] = set(block_ids)
        self._pending.append(
            TransferRecord(request.request_id, num_external_tokens, block_ids)
        )

    def build_connector_meta(self, scheduler_output):
        metadata = AsyncTransferMetadata(self._pending)
        self._pending = []
        return metadata

    def update_connector_output(self, connector_output):
        if connector_output.invalid_block_ids:
            invalid = connector_output.invalid_block_ids
            for request_id, block_ids in self._request_blocks.items():
                if block_ids & invalid:
                    self._matches[request_id] = 0
        return None

    def request_finished(self, request, block_ids):
        return False, None

    def take_events(self):
        return ()

    def start_load_kv(self, forward_context, **kwargs):
        metadata = self._get_connector_metadata()
        assert isinstance(metadata, AsyncTransferMetadata)
        for record in metadata.transfers:
            thread = threading.Thread(
                target=self._copy_transfer,
                args=(record,),
                name=f"async-kv-{record.request_id}",
                daemon=True,
            )
            thread.start()
            self._threads.append(thread)
        self.clear_connector_metadata()

    def _copy_transfer(self, record):
        time.sleep(self._delays.get(record.request_id, 0.002))
        source = bytes(
            (record.matched_tokens + offset) % 251
            for offset in range(max(64, record.matched_tokens * 8))
        )
        copied = bytearray(len(source))
        copied[:] = source
        checksum = hashlib.sha256(copied).hexdigest()
        invalid = None
        failure_index = self._failures.get(record.request_id)
        if failure_index is not None and 0 <= failure_index < len(record.block_ids):
            invalid = record.block_ids[failure_index]
        with self._lock:
            self._checksums[record.request_id] = checksum
            if invalid is not None:
                self._invalid_blocks.add(invalid)
            self._completed.add(record.request_id)

    def get_finished(self, finished_req_ids):
        with self._lock:
            completed = set(self._completed)
            self._completed.clear()
        return None, completed or None

    def get_block_ids_with_load_errors(self):
        with self._lock:
            invalid = set(self._invalid_blocks)
            self._invalid_blocks.clear()
        return invalid

    def wait_for_layer_load(self, layer_name):
        return None

    def save_kv_layer(self, layer_name, kv_layer, attn_metadata, **kwargs):
        return None

    def wait_for_save(self):
        return None

    def shutdown(self):
        for thread in self._threads:
            thread.join(timeout=5)

    @property
    def completed_checksums(self):
        with self._lock:
            return dict(self._checksums)


def tiny_model(path: Path) -> Path:
    path.mkdir(parents=True, exist_ok=True)
    (path / "config.json").write_text(
        json.dumps(
            {
                "architectures": ["OPTForCausalLM"],
                "model_type": "opt",
                "hidden_size": 64,
                "ffn_dim": 256,
                "num_attention_heads": 4,
                "num_hidden_layers": 2,
                "vocab_size": 512,
                "max_position_embeddings": 1024,
                "word_embed_proj_dim": 64,
                "do_layer_norm_before": True,
                "torch_dtype": "float32",
            }
        )
    )
    return path


def make_config(
    model_dir: Path,
    *,
    block_size: int,
    matches: dict[str, int],
    sync_request_ids=(),
    delays_ms=None,
    failure_block_index=None,
):
    model_config = ModelConfig(
        model=str(model_dir),
        dtype="float32",
        skip_tokenizer_init=True,
        max_model_len=1024,
    )
    scheduler_config = SchedulerConfig(
        max_model_len=1024,
        is_encoder_decoder=False,
        max_num_seqs=32,
        max_num_batched_tokens=4096,
        enable_chunked_prefill=True,
        disable_hybrid_kv_cache_manager=True,
    )
    cache_config = CacheConfig(
        block_size=block_size,
        gpu_memory_utilization=0.5,
        swap_space=0,
        enable_prefix_caching=True,
    )
    cache_config.num_gpu_blocks = 512
    transfer_config = KVTransferConfig(
        kv_connector="AsyncMemoryConnector",
        kv_connector_module_path="verifier_support",
        kv_role="kv_both",
        kv_buffer_device="cpu",
        kv_load_failure_policy="recompute",
        kv_connector_extra_config={
            "matches": matches,
            "sync_request_ids": list(sync_request_ids),
            "delays_ms": delays_ms or {},
            "failure_block_index": failure_block_index or {},
        },
    )
    return VllmConfig(
        model_config=model_config,
        scheduler_config=scheduler_config,
        cache_config=cache_config,
        device_config=DeviceConfig("cpu"),
        kv_transfer_config=transfer_config,
    )


def make_cache_config(block_size: int, num_blocks: int = 512):
    return KVCacheConfig(
        num_blocks=num_blocks,
        kv_cache_tensors=[],
        kv_cache_groups=[
            KVCacheGroupSpec(
                ["layer"],
                FullAttentionSpec(
                    block_size=block_size,
                    num_kv_heads=1,
                    head_size=1,
                    dtype=torch.float32,
                ),
            )
        ],
    )


def make_scheduler(model_dir: Path, *, block_size=16, num_blocks=512, **plan):
    config = make_config(
        model_dir,
        block_size=block_size,
        matches=plan.pop("matches"),
        **plan,
    )
    config.cache_config.num_gpu_blocks = num_blocks
    cache_config = make_cache_config(block_size, num_blocks)
    scheduler = Scheduler(
        vllm_config=config,
        kv_cache_config=cache_config,
        structured_output_manager=StructuredOutputManager(config),
        block_size=block_size,
        log_stats=False,
    )
    return scheduler, config, cache_config


_hash_initialized = False


def make_request(request_id: str, token_ids: list[int], *, block_size: int):
    global _hash_initialized
    if not _hash_initialized:
        init_none_hash(sha256)
        _hash_initialized = True
    return Request(
        request_id=request_id,
        prompt_token_ids=list(token_ids),
        sampling_params=SamplingParams(max_tokens=1),
        pooling_params=None,
        block_hasher=get_request_block_hasher(block_size, sha256),
    )


def tokens(length: int, salt: int = 0):
    return [((salt + index * 17) % 509) + 1 for index in range(length)]


def empty_output(kv_output=None):
    return ModelRunnerOutput(
        req_ids=[],
        req_id_to_index={},
        sampled_token_ids=[],
        logprobs=None,
        prompt_logprobs_dict={},
        pooler_output=[],
        kv_connector_output=kv_output,
    )


def sampled_output(scheduler_output, kv_output=None):
    request_ids = list(scheduler_output.num_scheduled_tokens)
    return ModelRunnerOutput(
        req_ids=request_ids,
        req_id_to_index={req_id: index for index, req_id in enumerate(request_ids)},
        sampled_token_ids=[[7] for _ in request_ids],
        logprobs=None,
        prompt_logprobs_dict={},
        pooler_output=[],
        kv_connector_output=kv_output,
    )


def make_worker(config, cache_config):
    return KVConnectorFactory.create_connector(
        config,
        KVConnectorRole.WORKER,
        cache_config,
    )


def start_worker_transfer(worker, scheduler_output):
    worker.bind_connector_metadata(scheduler_output.kv_connector_metadata)
    worker.start_load_kv(None)


def wait_for_worker_output(worker, *, timeout=5):
    deadline = time.monotonic() + timeout
    while time.monotonic() < deadline:
        _, finished = worker.get_finished(set())
        invalid = worker.get_block_ids_with_load_errors()
        if finished or invalid:
            return KVConnectorOutput(
                finished_recving=finished,
                invalid_block_ids=invalid,
            )
        time.sleep(0.005)
    raise TimeoutError("asynchronous connector did not finish")

#!/usr/bin/env python3
"""Run 24 requests through eleven reset, stale-output, and resume cycles."""

from __future__ import annotations

import tempfile
from pathlib import Path

from verifier_support import (
    activate_requests,
    assert_stale_frame_did_not_change_fresh_state,
    capture_spec_frame,
    deliver,
    make_requests,
    make_scheduler,
    model_output,
    resume_after_reset,
    snapshot,
)


def main() -> int:
    try:
        with tempfile.TemporaryDirectory(prefix="async-spec-reset-e2e-") as temp_dir:
            scheduler = make_scheduler(Path(temp_dir) / "model", max_num_seqs=32)
            requests = make_requests(24, max_tokens=128, token_seed=300)
            activate_requests(scheduler, requests)
            draft_widths = [1, 2, 3, 5, 7, 2, 5, 1, 7, 3, 5]
            progress_events = 0
            stale_frames_delivered = 0

            for cycle, num_drafts in enumerate(draft_widths):
                stale_output = capture_spec_frame(
                    scheduler,
                    requests,
                    num_drafts=num_drafts,
                    num_accepted=cycle % (num_drafts + 1),
                )
                fresh_output = resume_after_reset(scheduler, requests)
                fresh_snapshots = {
                    request.request_id: snapshot(request) for request in requests
                }

                for stale_index in range(num_drafts + 1):
                    scheduler.update_from_output(
                        stale_output,
                        model_output(
                            stale_output,
                            token_seed=1000 + cycle * 200 + stale_index * 20,
                        ),
                    )
                    stale_frames_delivered += len(requests)
                    for request in requests:
                        assert_stale_frame_did_not_change_fresh_state(
                            request,
                            fresh_snapshots[request.request_id],
                        )

                before_lengths = {
                    request.request_id: len(request.output_token_ids)
                    for request in requests
                }
                deliver(
                    scheduler,
                    fresh_output,
                    accepted=0,
                    token_seed=5000 + cycle * 100,
                )
                for request in requests:
                    assert request.num_output_placeholders >= 0
                    assert len(request.output_token_ids) == (
                        before_lengths[request.request_id] + 1
                    )
                    progress_events += 1

        print(
            {
                "entrypoint": "AsyncScheduler schedule/reset/update lifecycle",
                "concurrent_requests": 24,
                "reset_cycles": len(draft_widths),
                "draft_widths": draft_widths,
                "stale_request_frames_delivered": stale_frames_delivered,
                "normal_progress_events": progress_events,
                "negative_placeholder_events": 0,
            },
            flush=True,
        )
        return 0
    except Exception as exc:
        print(
            {
                "error": type(exc).__name__,
                "message": str(exc).splitlines()[0] if str(exc) else "no message",
            },
            flush=True,
        )
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

#define _GNU_SOURCE

#include <dlfcn.h>
#include <errno.h>
#include <fcntl.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdlib.h>
#include <string.h>
#include <sys/syscall.h>
#include <unistd.h>

static int matching_open_count = 0;
static int failure_consumed = 0;
static int corrupt_fd = -1;

static int worker_index(void) {
    char command[4096];
    long fd = syscall(SYS_openat, AT_FDCWD, "/proc/self/cmdline", O_RDONLY, 0);
    if (fd < 0) return -1;
    long count = syscall(SYS_read, fd, command, sizeof(command) - 1);
    syscall(SYS_close, fd);
    if (count <= 0) return -1;
    command[count] = '\0';
    if (strstr(command, "APIServer_0") != NULL) return 0;
    if (strstr(command, "APIServer_1") != NULL) return 1;
    return -1;
}

static bool target_path(const char *path) {
    const char *expected = getenv("AIB_FAIL_CONFIG_PATH");
    return path != NULL && expected != NULL && strcmp(path, expected) == 0;
}

static void marker(const char *message) {
    const char *path = getenv("AIB_FAULT_MARKER_PATH");
    if (path == NULL) return;
    long fd = syscall(SYS_openat, AT_FDCWD, path,
                      O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd >= 0) {
        syscall(SYS_write, fd, message, strlen(message));
        syscall(SYS_close, fd);
    }
}

static int prepare_open(const char *path) {
    int worker = worker_index();
    if (worker < 0 || !target_path(path)) return -1;
    int current = __sync_add_and_fetch(&matching_open_count, 1);
    if (current != 2 || !__sync_bool_compare_and_swap(&failure_consumed, 0, 1)) {
        return -1;
    }
    if (worker == 0) {
        marker("ApiServer_0 ENOENT\n");
        return 0;
    }
    return 1;
}

static mode_t optional_mode(int flags, va_list args) {
    if ((flags & O_CREAT) || (flags & O_TMPFILE) == O_TMPFILE) {
        return va_arg(args, mode_t);
    }
    return 0;
}

#define DEFINE_OPEN(name, real_type, call_args, params)                        \
int name params {                                                               \
    static real_type real_fn = NULL;                                             \
    if (real_fn == NULL) real_fn = dlsym(RTLD_NEXT, #name);                     \
    va_list args; va_start(args, flags);                                         \
    mode_t mode = optional_mode(flags, args); va_end(args);                     \
    int action = prepare_open(path);                                             \
    if (action == 0) { errno = ENOENT; return -1; }                             \
    int fd = real_fn call_args;                                                  \
    if (action == 1 && fd >= 0) corrupt_fd = fd;                                \
    return fd;                                                                   \
}

